import inspect
from asyncio import iscoroutinefunction
from functools import cached_property, partial
from typing import Any, Callable, Optional, List
from dataclasses import dataclass, field

def _unwrapped_call(call: Optional[Callable[..., Any]]) -> Any:
    if call is None:
        return call
    unwrapped = inspect.unwrap(_impartial(call))
    return unwrapped

def _impartial(func: Callable[..., Any]) -> Callable[..., Any]:
    while isinstance(func, partial):
        func = func.func
    return func

@dataclass
class Dependant:
    call: Optional[Callable[..., Any]] = None

    @cached_property
    def is_gen_callable(self) -> bool:
        if self.call is None:
            return False
        if inspect.isgeneratorfunction(
            _impartial(self.call)
        ) or inspect.isgeneratorfunction(_unwrapped_call(self.call)):
            return True
        dunder_call = getattr(_impartial(self.call), "__call__", None)
        if dunder_call is None:
            return False
        if inspect.isgeneratorfunction(
            _impartial(dunder_call)
        ) or inspect.isgeneratorfunction(_unwrapped_call(dunder_call)):
            return True
        dunder_unwrapped_call = getattr(_unwrapped_call(self.call), "__call__", None)
        if dunder_unwrapped_call is None:
            return False
        if inspect.isgeneratorfunction(
            _impartial(dunder_unwrapped_call)
        ) or inspect.isgeneratorfunction(_unwrapped_call(dunder_unwrapped_call)):
            return True
        return False

    @cached_property
    def is_async_gen_callable(self) -> bool:
        if self.call is None:
            return False
        if inspect.isasyncgenfunction(
            _impartial(self.call)
        ) or inspect.isasyncgenfunction(_unwrapped_call(self.call)):
            return True
        dunder_call = getattr(_impartial(self.call), "__call__", None)
        if dunder_call is None:
            return False
        if inspect.isasyncgenfunction(
            _impartial(dunder_call)
        ) or inspect.isasyncgenfunction(_unwrapped_call(dunder_call)):
            return True
        dunder_unwrapped_call = getattr(_unwrapped_call(self.call), "__call__", None)
        if dunder_unwrapped_call is None:
            return False
        if inspect.isasyncgenfunction(
            _impartial(dunder_unwrapped_call)
        ) or inspect.isasyncgenfunction(_unwrapped_call(dunder_unwrapped_call)):
            return True
        return False

    @cached_property
    def is_coroutine_callable(self) -> bool:
        if self.call is None:
            return False
        if inspect.isroutine(_impartial(self.call)) and iscoroutinefunction(
            _impartial(self.call)
        ):
            return True
        if inspect.isroutine(_unwrapped_call(self.call)) and iscoroutinefunction(
            _unwrapped_call(self.call)
        ):
            return True
        dunder_call = getattr(_impartial(self.call), "__call__", None)
        if dunder_call is None:
            return False
        if iscoroutinefunction(_impartial(dunder_call)) or iscoroutinefunction(
            _unwrapped_call(dunder_call)
        ):
            return True
        dunder_unwrapped_call = getattr(_unwrapped_call(self.call), "__call__", None)
        if dunder_unwrapped_call is None:
            return False
        if iscoroutinefunction(
            _impartial(dunder_unwrapped_call)
        ) or iscoroutinefunction(_unwrapped_call(dunder_unwrapped_call)):
            return True
        return False

class MyGenDep:
    def __call__(self):
        yield 1

class MyAsyncGenDep:
    async def __call__(self):
        yield 1

class MyCoroutineDep:
    async def __call__(self):
        return 1

def test_repro():
    # Test is_gen_callable
    dep_gen = Dependant(call=MyGenDep)
    print(f"MyGenDep is_gen_callable: {dep_gen.is_gen_callable} (expected: False)")

    # Test is_async_gen_callable
    dep_async_gen = Dependant(call=MyAsyncGenDep)
    print(f"MyAsyncGenDep is_async_gen_callable: {dep_async_gen.is_async_gen_callable} (expected: False)")

    # Test is_coroutine_callable
    dep_coro = Dependant(call=MyCoroutineDep)
    print(f"MyCoroutineDep is_coroutine_callable: {dep_coro.is_coroutine_callable} (expected: False)")

    # Also test with instances to make sure they still work
    inst_gen = Dependant(call=MyGenDep())
    print(f"MyGenDep() is_gen_callable: {inst_gen.is_gen_callable} (expected: True)")

    inst_async_gen = Dependant(call=MyAsyncGenDep())
    print(f"MyAsyncGenDep() is_async_gen_callable: {inst_async_gen.is_async_gen_callable} (expected: True)")

    inst_coro = Dependant(call=MyCoroutineDep())
    print(f"MyCoroutineDep() is_coroutine_callable: {inst_coro.is_coroutine_callable} (expected: True)")

if __name__ == "__main__":
    test_repro()

